class Inner(torch.nn.Module):
    def forward(self, x):
        x = x + 1
        torch._dynamo.graph_break()
        return x * 2

class Loop(torch.nn.Module):
    def __init__(s): super().__init__(); s.l = torch.nn.ModuleList([Inner(), Inner()])
    def forward(self, x):
        x = x.sin()
        for m in self.l:
            x = m(x)
        return x.cos()

class Unrolled(torch.nn.Module):
    def __init__(s): super().__init__(); s.l = torch.nn.ModuleList([Inner(), Inner()])
    def forward(self, x):
        x = x.sin()
        x = self.l[0](x)
        x = self.l[1](x)
        return x.cos()
